// Best-effort HMAC verification. Django signs X-Signature = HMAC-SHA256(
// N8N_SHARED_SECRET, raw compact JSON body). NOTE: n8n's raw-body access varies
// by version, so this is observability-only and does NOT block delivery — enforce
// signatures with n8n native Header Auth or a network control in production.
const crypto = require('crypto');
const secret = $env.N8N_SHARED_SECRET || '';
const items = $input.all();
let headers = {};
try { headers = ($input.first().json.headers) || {}; } catch (e) {}
const sig = headers['x-signature'] || headers['X-Signature'] || '';
let raw = '';
try {
  const j = $input.first().json;
  raw = (typeof j.body === 'string') ? j.body : JSON.stringify(j.body != null ? j.body : j);
} catch (e) { raw = ''; }
let valid = false;
try {
  if (secret && sig && raw) {
    const expected = crypto.createHmac('sha256', secret).update(raw, 'utf8').digest('hex');
    valid = (expected.length === sig.length) &&
            crypto.timingSafeEqual(Buffer.from(expected), Buffer.from(sig));
  }
} catch (e) { valid = false; }
return items.map(it => ({ json: Object.assign({}, it.json, { _signature_valid: valid }) }));

// Multilingual decision email; branches on the event (approved / rejected / refund.completed).
const p = $input.first().json;
const lang = (p.language || 'en').toLowerCase();
const d = p.data || {};
const ev = p.event || 'return.approved';
const sym = { EUR: '€', USD: '$', GBP: '£' }[d.currency] || (d.currency ? d.currency + ' ' : '');
const money = (v) => sym + Number(v || 0).toFixed(2);

const dict = {
  en: {
    approved: { subject: `Your return for order ${d.order_number} was approved`, body: 'Good news — your return request has been approved. Please follow the instructions to send the item back.' },
    rejected: { subject: `Update on your return for order ${d.order_number}`, body: 'After review, we are unable to approve this return request.' },
    refund: { subject: `Refund issued for order ${d.order_number}`, body: `Your refund of ${money(d.refund_amount)} has been processed and should appear on your statement within a few business days.` },
    hi: `Hi ${d.first_name || ''},`, note: 'Note', view: 'View your return', thanks: 'Thank you — Glitchy.'
  },
  it: {
    approved: { subject: `Il tuo reso per l’ordine ${d.order_number} è stato approvato`, body: 'Buone notizie — la tua richiesta di reso è stata approvata. Segui le istruzioni per rispedire l’articolo.' },
    rejected: { subject: `Aggiornamento sul tuo reso per l’ordine ${d.order_number}`, body: 'Dopo una verifica, non possiamo approvare questa richiesta di reso.' },
    refund: { subject: `Rimborso effettuato per l’ordine ${d.order_number}`, body: `Il tuo rimborso di ${money(d.refund_amount)} è stato elaborato e comparirà sul tuo estratto conto entro pochi giorni lavorativi.` },
    hi: `Ciao ${d.first_name || ''},`, note: 'Nota', view: 'Vedi il tuo reso', thanks: 'Grazie — Glitchy.'
  },
  fr: {
    approved: { subject: `Votre retour pour la commande ${d.order_number} a été approuvé`, body: 'Bonne nouvelle — votre demande de retour a été approuvée. Veuillez suivre les instructions pour renvoyer l’article.' },
    rejected: { subject: `Mise à jour de votre retour pour la commande ${d.order_number}`, body: 'Après examen, nous ne pouvons pas approuver cette demande de retour.' },
    refund: { subject: `Remboursement effectué pour la commande ${d.order_number}`, body: `Votre remboursement de ${money(d.refund_amount)} a été traité et apparaîtra sur votre relevé sous quelques jours ouvrés.` },
    hi: `Bonjour ${d.first_name || ''},`, note: 'Remarque', view: 'Voir votre retour', thanks: 'Merci — Glitchy.'
  }
};
const L = dict[lang] || dict.en;
const branch = ev === 'return.rejected' ? L.rejected : (ev === 'refund.completed' ? L.refund : L.approved);

const btn = d.return_url ? `<p style="margin:18px 0"><a href="${d.return_url}" style="background:#111;color:#fff;padding:10px 18px;text-decoration:none;border-radius:6px;display:inline-block">${L.view}</a></p>` : '';
const html = `<div style="font-family:Arial,Helvetica,sans-serif;max-width:600px;margin:auto;color:#222">
<h2 style="color:#111">${branch.subject}</h2>
<p>${L.hi}</p>
<p>${branch.body}</p>
${d.admin_note ? `<p><strong>${L.note}:</strong> ${d.admin_note}</p>` : ''}
${btn}
<p style="margin-top:20px;color:#666">${L.thanks}</p>
</div>`;

return [{ json: { to: p.recipient, subject: branch.subject, html } }];
